// Extrae el payload del webhook y normaliza los datos.
// El webhook de n8n puede entregar el cuerpo como $json (directo) o como $json.body.
const raw = $input.first().json || {};
const bodyObj = (raw.body && typeof raw.body === 'object') ? raw.body : raw;
const p = (bodyObj.payload && typeof bodyObj.payload === 'object') ? bodyObj.payload : bodyObj;
return [{
  json: {
    session_id: p.session_id || '',
    usuario_id: (p.usuario_id !== undefined && p.usuario_id !== null) ? p.usuario_id : null,
    mensaje: p.mensaje || '',
    historial: Array.isArray(p.historial) ? p.historial : []
  }
}];

// Construye el prompt completo del chatbot: instruccion + rol + historial + contexto + mensaje.
const datos = $('Extraer datos').first().json;
const ctx = $input.first().json; // respuesta de 'Obtener contexto' (backend seguro)
const historial = (datos.historial || [])
  .map((m) => (m.rol === 'user' ? 'Usuario: ' : 'Bot: ') + m.contenido)
  .join('\n');

// Contexto del usuario segun rol (el backend solo devuelve datos del dueno de la sesion).
let contextoTexto = 'Usuario: NO autenticado (invitado). No tiene datos personales visibles. Si pide algo personal (pedidos, adopciones, favoritos) o ir a una seccion protegida, indica que primero debe iniciar sesion o registrarse.';
if (ctx && ctx.autenticado) {
  const rol = ctx.rol || 'usuario';
  const rolNombre = { usuario: 'usuario adoptante', refugio: 'representante de refugio', empleado_refugio: 'empleado de refugio', tienda_aliada: 'miembro de tienda aliada', administrador: 'administrador' }[rol] || rol;
  contextoTexto = 'Usuario AUTENTICADO. Rol: ' + rolNombre + '.\nNombre: ' + (ctx.usuario ? (ctx.usuario.nombre || '') : '') + '\n';
  const pedidos = Array.isArray(ctx.pedidos) ? ctx.pedidos : [];
  contextoTexto += (pedidos.length ? 'Sus pedidos:\n' + pedidos.map((p) => '- ' + (p.numero || p.id) + ': ' + (p.estado_nombre || p.estado || '?')).join('\n') + '\n' : 'Sus pedidos: (sin pedidos)\n');
  const adop = Array.isArray(ctx.adopciones) ? ctx.adopciones : [];
  contextoTexto += (adop.length ? 'Sus solicitudes de adopcion:\n' + adop.map((a) => '- ' + a.mascota + ': ' + a.estado + ' (progreso ' + a.progreso + '%)').join('\n') + '\n' : 'Sus solicitudes de adopcion: (sin adopciones)\n');
  if (ctx.refugio) contextoTexto += 'Su refugio: ' + ctx.refugio.nombre + '\n';
  if (ctx.tienda) contextoTexto += 'Su tienda: ' + ctx.tienda.nombre + '\n';
}

const instruccion = 'Eres el asistente virtual de Adoptify, una plataforma de adopcion de mascotas que conecta refugios, tiendas aliadas y adoptantes. Ayudas a las personas a entender la plataforma, el proceso de adopcion, el cuidado de mascotas, los refugios, la tienda y el foro. Respondes en espanol con un tono amable, cercano y claro. Puedes responder dudas generales (adopcion, cuidado, requisitos, como funciona la pagina) de forma natural y util, sin limitarte solo a navegar. Responde SOLO JSON con esta forma exacta: {"respuesta": "tu mensaje al usuario", "accion": null}. Si el usuario quiere IR A una seccion de la pagina, devuelve accion como {"tipo": "navegar", "ruta": "/..."} usando SOLO una de estas rutas reales: / (inicio), /animals (mascotas en adopcion), /shelters (refugios), /store (tienda), /forum (foro), /mis-pedidos (mis pedidos), /favoritos (mis favoritos), /login, /register, /registrar-refugio, /registrar-tienda. Si no aplica navegacion, accion: null.\n\nIMPORTANTE ROL Y ACCESO: Conoces el rol del usuario (invitado, usuario, refugio, empleado_refugio, tienda_aliada, administrador) por el CONTEXTO y adaptas tu respuesta a ese rol. Si el usuario NO esta autenticado y pide algo personal (estado de sus adopciones, pedidos, favoritos) o una seccion protegida (mascotas, refugios, tienda, foro, mis pedidos, favoritos), responde con una frase amable como: "Para eso primero debes iniciar sesion o registrarte" y sugiere la ruta /login. Si es empleado de una tienda o refugio, ten en cuenta que puede no tener todos los permisos; orientalo a su representante o a soporte. Usa el CONTEXTO (historial, pedidos y adopciones) para responder sobre el estado real de sus solicitudes; no inventes datos ni consultes nada fuera de lo dado.\n\n';

const prompt = instruccion +
  'CONTEXTO DEL USUARIO:\n' + contextoTexto +
  '\n\nHISTORIAL DE LA CONVERSACION:\n' + historial +
  '\n\nMENSAJE DEL USUARIO:\n' + (datos.mensaje || '');

return [{ json: { prompt } }];

// Extrae y valida la respuesta del AI Agent ($json.output) para el formato esperado.
const r = $input.all()[0].json;
let texto = (typeof r.output === 'string') ? r.output : (r.output ? JSON.stringify(r.output) : '');
texto = String(texto || '').trim();
if (texto.startsWith('```json')) texto = texto.slice(7);
else if (texto.startsWith('```')) texto = texto.slice(3);
if (texto.endsWith('```')) texto = texto.slice(0, -3);
let res = {};
try {
  res = JSON.parse(texto.trim());
} catch (e) {
  res = {};
}
let accion = null;
if (res.accion && res.accion.tipo === 'navegar' && typeof res.accion.ruta === 'string') {
  accion = { tipo: 'navegar', ruta: res.accion.ruta };
}
const respuesta = res.respuesta || (texto && !res.accion ? texto : null) || 'Hola, ¿en qué te ayudo?';
return [{ json: { respuesta, accion } }];
